import copy,json
from work import evaluate
reqs=json.load(open('requests.json')); ev=json.load(open('evidence.json')); pol=json.load(open('policy.json'))
report=json.load(open('report.json'))
assert report == [evaluate(r,ev,pol) for r in reqs]
assert all(set(x)=={'status','value','sources','unknowns'} for x in report)
req={'claim':'probe','conditions':{'recipe':'R','material':'M'}}
old={'source':'old','claim':'probe','value':1,'conditions':{'recipe':'R','material':'M'}}
withdrawn_new={'source':'new','claim':'probe','value':2,'conditions':{'recipe':'R','material':'M'},'withdrawn':True,'supersedes':['old']}
unverified_new={'source':'new','claim':'probe','value':2,'conditions':{'recipe':'R','material':'M'},'verified':False,'supersedes':['old']}
p={'required_conditions':['recipe','material'],'require_verified':False}
assert evaluate(req,[old,withdrawn_new],p)=={'status':'supported','value':1,'sources':['old'],'unknowns':[]}
pv={'required_conditions':['recipe','material'],'require_verified':True}
oldv=copy.deepcopy(old); oldv['verified']=True
assert evaluate(req,[oldv,unverified_new],pv)=={'status':'supported','value':1,'sources':['old'],'unknowns':[]}
assert evaluate(req,[{'source':'n','claim':'probe','value':7,'conditions':{'recipe':'R','material':'M','calibration':'present'}}],p)=={'status':'supported','value':7,'sources':['n'],'unknowns':[]}
print('final contract checks passed')
